INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q720801', 'Battle of Cecora', 'The Battle of Cecora (also known as the Battle of Țuțora) took place on October 19–20, 1595, during an expedition of Jan Zamoyski, of the Polish–Lithuanian Commonwealth, to Moldavia, as part of the Moldavian Magnate Wars.', 1595, 10, 19, 1595, 10, 20, 'day', '19 October 1595 – 20 October 1595', 39, 'https://en.wikipedia.org/wiki/Battle_of_Cecora_(1595)'),
  ('Q4087393', 'Battle of Pererîta', 'The Battle of Pererîta was a clash between the troops of the Polish–Lithuanian Commonwealth and Turkish–Tatar detachments on 13 September 1691 in the village of Pererîta, located in present-day Moldova. The battle was part of the Polish campaign against Moldavia, taking place within the broader context of the Polish–Ottoman War (1683–1699) and the Great Turkish War, and resulted in a Polish–Lithuanian victory.', 1691, 9, 13, NULL, NULL, NULL, 'day', '13 September 1691', 34, 'https://en.wikipedia.org/wiki/Battle_of_Perer%C3%AEta'),
  ('Q638601', 'Skirmish at Bender', 'The Skirmish at Bender (Swedish: Kalabaliken i Bender; Finnish: Benderin kalabaliikki; Russian: Перестрелка в Бендерах, romanized: Perestrelka v Benderakh) was devised to remove Charles XII of Sweden from the Ottoman Empire after his military defeats in Russia. It took place on 1 February 1713 (O.S.) or 12 February 1713 (N.S.) on Ottoman territory, in what is now the town of Bender, Moldova (separatist region of Transnistria).', 1713, 2, 1, NULL, NULL, NULL, 'day', '1 February 1713', 53, 'https://en.wikipedia.org/wiki/Skirmish_at_Bender'),
  ('Q702189', 'Treaty of Niš', 'The Treaty of Niš was a peace treaty signed on 3 October 1739 in Niš (nowadays in Serbia), by the Ottoman Empire and the Russian Empire, to end the Russo-Turkish War (1735–1739). It was preceded by the preliminary Russo-Turkish peace treaty, signed through French mediation on 18 September 1739 in Belgrade, while the peace arrangements were finalized by the treaty of Niš on 3 October.', 1739, NULL, NULL, NULL, NULL, NULL, 'year', '1739', 63, 'https://en.wikipedia.org/wiki/Treaty_of_Ni%C5%A1_(1739)'),
  ('Q700218', 'Battle of Kagul', 'The Battle of Kagul or Cahul (Russian: Сражение при Кагуле, lit. ''Battle of the Kagul'', Turkish: Kartal Ovası Muharebesi, lit. ''Battle of the Eagle Plain'') occurred on 1 August 1770 (21 July 1770 in Julian Calendar) during the Russo-Turkish War of 1768–1774. It was the decisive and most important land battle of the war and one of the largest battles of the 18th century.', 1770, 8, 1, NULL, NULL, NULL, 'day', '1 August 1770', 56, 'https://en.wikipedia.org/wiki/Battle_of_Kagul'),
  ('Q48940579', 'Siege of Bender', 'The siege of Bender (Russian: Осада Бендер, romanized: Osada Bender) was a military conflict of the Russo-Turkish War of 1768–1774. The 2nd Russian Army, led by Count Petr Ivanovich Panin, took the Turkish fortress of Bender, located in modern-day Moldova.', 1770, 7, 15, 1770, 9, 16, 'day', '15 July 1770 – 16 September 1770', 34, 'https://en.wikipedia.org/wiki/Siege_of_Bender_(1770)'),
  ('Q4896386', 'Bessarabian question', 'The Bessarabian question, Bessarabian issue or Bessarabian problem (Romanian: Problema basarabeană or chestiunea basarabeană; Russian: Бессарабский вопрос or бессарабская проблема; Ukrainian: Бессарабське питання or Бессарабська проблема) is the name given to the controversy over the ownership of the geographic region of Bessarabia that began with the annexation of the region by the Russian Empire from the Romanian principality of Moldavia in 1812 through the Treaty of Bucharest and which continued with the independence and union of Bessarabia with Romania in 1917, the occupation and…', 1812, NULL, NULL, 1997, NULL, NULL, 'year', '1812–1997', 39, 'https://en.wikipedia.org/wiki/Bessarabian_question'),
  ('Q2093780', 'Battle of Skuleni', 'The Battle of Sculeni was fought on 29 June 1821 in Sculeni, Moldavia between Ottoman forces and the Greek revolutionary forces raised by the Filiki Eteria led by Prince George Katakouzenos. The battle came about as the result of Ottoman reprisals for Alexander Ypsilantis'' expedition in the two Danubian Principalities, and followed in the aftermath of the Battle of Drăgășani.', 1821, 7, 11, NULL, NULL, NULL, 'day', '11 July 1821', 37, 'https://en.wikipedia.org/wiki/Battle_of_Sculeni'),
  ('Q4083702', 'Bender Uprising', 'The Bender Uprising was organized by local Bolshevik groups in Bender/Tighina on 27 May 1919, as a protest of the local Russian population against the annexation of Bessarabia by the Kingdom of Romania in December 1918 (united in a federation with Romania since April 1918, Bessarabia was annexed by the latter on 10 December). Red Guards from local factories were organized under the command of Grigoriy Borisov, and were supported by 150 troops of the 3rd Brigade of the 5th Division of the 3rd Ukrainian Soviet Army.', 1919, 5, 27, NULL, NULL, NULL, 'day', '27 May 1919', 43, 'https://en.wikipedia.org/wiki/Bender_Uprising'),
  ('Q2266004', 'Soviet occupation of Bessarabia and Northern Bukovina', 'Between 28 June and 3 July 1940, the Soviet Union occupied Bessarabia, Northern Bukovina and the Hertsa region, following an ultimatum made to Romania on 26 June 1940 that threatened the use of force. Those regions, with a total area of 50,762 km2 (19,599 sq mi) and a population of 3,776,309 inhabitants, were incorporated into the Soviet Union.', 1940, 6, 28, 1940, 7, 3, 'day', '28 June 1940 – 3 July 1940', 63, 'https://en.wikipedia.org/wiki/Soviet_occupation_of_Bessarabia_and_Northern_Bukovina'),
  ('Q3376121', 'The Holocaust in Romania', 'The Holocaust saw the genocide of Jews in the Kingdom of Romania and in Romanian-controlled territories of the Soviet Union between 1940 and 1944. While historically part of The Holocaust, these actions were mostly independent from the similar acts committed by Nazi Germany, Romania being the only ally of the Third Reich that carried out a genocidal campaign without the intervention of Heinrich Himmler''s SS. Various numbers have been advanced by researchers for the lives lost in the genocide, with most estimates in the range of 250,000 to 380,000.', 1941, NULL, NULL, 1943, NULL, NULL, 'year', '1941–1943', 48, 'https://en.wikipedia.org/wiki/The_Holocaust_in_Romania'),
  ('Q715700', 'First Jassy–Kishinev Offensive', 'The first Jassy–Kishinev offensive, named after the two major cities in the area, Jassy and Kishinev, was a series of military engagements between 8 April and 6 June 1944 (according to David Glantz) by the Soviet Union and Axis powers. Richard C. Hall also refers to a first Jassy–Kishinev operation which began on 5 April, without providing an exact date for its end.', 1944, 6, 6, 1944, 6, 6, 'day', '6 June 1944', 57, 'https://en.wikipedia.org/wiki/First_Jassy%E2%80%93Kishinev_offensive'),
  ('Q751139', '1977 Vrancea earthquake', 'The 1977 Vrancea earthquake occurred on 4 March 1977, at 21:22 local time, and was felt throughout the Balkans. It had a magnitude of 7.5, making it the second most powerful earthquake recorded in Romania in the 20th century, after the 10 November 1940 seismic event.', 1977, 3, 4, NULL, NULL, NULL, 'day', '4 March 1977', 62, 'https://en.wikipedia.org/wiki/1977_Vrancea_earthquake'),
  ('Q4300306', 'Gagauzia conflict', 'The Gagauzia conflict (Gagauz: Gagauziya çatışmaları; Romanian: Conflictul din Găgăuzia) was a conflict between the Moldavian SSR and posteriorly the independent Republic of Moldova and their Gagauz population, which sought further autonomy within Moldova. It culminated in the declaration of the Gagauz Republic, separate from Moldavia, with the aim of remaining within the Soviet Union; however, following the latter''s dissolution, the Gagauz Republic became a de facto independent state.', 1989, 11, 12, 1995, 1, 14, 'day', '12 November 1989 – 14 January 1995', 48, 'https://en.wikipedia.org/wiki/Gagauzia_conflict'),
  ('Q285280', 'Transnistria War', 'The Transnistrian War (Romanian: Războiul din Transnistria; Russian: Война в Приднестровье, romanized: Voyna v Pridnestrovye) was an armed conflict that broke out on 2 November 1990 in Dubăsari between pro-separatist (Pridnestrovian Moldavian Republic, PMR; Transnistria) forces, including the Transnistrian Republican Guard, militia and neo-Cossack units, which were supported by elements of the Russian 14th Army, and pro-government forces, including Moldovan troops and police. Fighting intensified on 1 March 1992 and, alternating with ad hoc ceasefires, lasted throughout the spring and early…', 1990, 11, 2, 1992, 7, 21, 'day', '2 November 1990 – 21 July 1992', 73, 'https://en.wikipedia.org/wiki/Transnistrian_War'),
  ('Q4087298', 'Battle of Bender', 'The Battle of Bender, also known as the Battle of Tighina or the Battle of Bendery (Romanian: Bătălia de la Tighina; Russian: Битва за Бендеры, romanized: Bitva za Bendery), was fought between 19 and 21 June 1992 between Moldova, backed by volunteers, military advisors and purchased weapons sourced from Romania; and the Pridnestrovian Moldavian Republic (PMR, commonly known as Transnistria), an unrecognized breakaway state that declared independence from Moldova and relied on direct military support from Russia. The battle occurred in Bender, also known as Tighina, a city with a strong…', 1992, 6, 19, 1992, 6, 24, 'day', '19 June 1992 – 24 June 1992', 45, 'https://en.wikipedia.org/wiki/Battle_of_Bender_(1992)'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q385065', 'April 2009 Moldovan parliamentary election protests', 'Protests against the April 2009 Moldovan parliamentary election results began on 6 April 2009 in major cities of Moldova (including Bălți and the capital, Chișinău) before the final official results were announced. The demonstrators claimed that the election, which saw the governing Party of Communists of the Republic of Moldova (PCRM) win a majority of seats, were fraudulent, and alternatively demanded a recount, a new election, or resignation of the government.', 2009, 4, 12, NULL, NULL, NULL, 'day', '12 April 2009', 57, 'https://en.wikipedia.org/wiki/April_2009_Moldovan_parliamentary_election_protests'),
  ('Q20646777', '2015 Moldovan protests', 'Starting in the spring of 2015, Moldova experienced large-scale protests amid a worsening economic situation and corruption scandals. The protests gained momentum in September, when up to 100,000 people demonstrated in the largest protest since Moldova''s independence from the Soviet Union in August 1991.', 2015, NULL, NULL, 2016, 11, 13, 'year', '2015 – 13 November 2016', 45, 'https://en.wikipedia.org/wiki/2015%E2%80%932016_protests_in_Moldova'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe');
